public void TouchWay(int row, int way, bool fill) {
    if (replacement == "LRU" || replacement == "FIFO" && fill)
        touched[row][way] = ++clock;
    else if (replacement == "PLRU") {
        int low = 0, high = ways, node = 1;
        while (high - low > 1) {
            int mid = (low + high) / 2;
            if (way < mid) {
                bits[row][node] = 1;
                high = mid;
                node *= 2;
            } else {
                bits[row][node] = 0;
                low = mid;
                node = 2 * node + 1;
            }
        }
    }
}
public void Touch(int block) {
    Location p = Locate(block);
    if (p != null)
        TouchWay(p.row, p.way, false);
}
public static Request Requester(string protocol, string old, string op, bool otherHasLine) {
    if (protocol == "VI")
        return op == "R" ? new(old == "I" ? "BusRd" : null, "V")
                         : new("BusWr", old == "I" ? "I" : "V");
    if (old == "I")
        return op == "W" ? new("BusRdX", "M")
                         : new("BusRd", protocol != "MSI" && !otherHasLine ? "E" : "S");
    if (op == "R")
        return new(null, old);
    return old == "M" || old == "E" ? new(null, "M") : new("BusUpgr", "M");
}
